\title{An Explicit Quantitative Power-Saving Corridor \\ for Monic Minkowski Polynomials}
\author{Aristotle}
\date{2026-07-06}

\begin{document}
\maketitle

\begin{abstract}
For a finite set $A \subseteq \Z$ and a polynomial $f \in \Z[x]$, the \emph{Minkowski image}
(elementwise image) is $f(A) = \{f(a) : a \in A\}$. Power-saving estimates for $\card{f(A)}$
are a recurring theme in additive combinatorics; the deepest results are asymptotic and rely
on incidence geometry. In this paper we isolate and prove unconditionally the exact finitary
skeleton underlying every such estimate. For a monic $f$ of degree $k \ge 2$ and nonempty
finite $A$, we establish the two-sided corridor
\[
  \frac{\card{A}}{k} \;\le\; \card{f(A)} \;\le\; \card{A}^{\,k - 1/k^2},
\]
with the explicit power-saving constant $c(k) = 1/k^2$. We prove that both walls are
essentially attained: $f(x)=x^k$ on an arithmetic progression saturates the upper wall (no
expansion), and $f(x)=x^2$ on a symmetric window saturates the lower wall up to a single
unavoidable fixed-point term, via the exact identity $2\card{f(A)} = \card{A}+1$. Finally, we
show the fiber lower bound is \emph{multiplicative under composition}: for $\deg p = k$ and
$\deg q = m$ one has $\card{A} \le (k m)\card{(q\circ p)(A)}$, matching
$\deg(q\circ p) = k m$, so an $r$-fold tower of degree-$k$ maps carries the explicit constant
$c = 1/k^{2r}$. The proof of multiplicativity chains two independent fiber bounds through the
intermediate image $p(A)$, exhibiting the corridor as a genuine multiplicative (functorial)
structure rather than a rewrapping of the single-map bound.
\end{abstract}

\section{Introduction}

\subsection{The Minkowski image and the size question}
Let $A$ be a finite subset of the integers and let $f \in \Z[x]$ be a polynomial. The central
object is the \emph{Minkowski image} (elementwise image)
\[
  f(A) = \{\, f(a) : a \in A \,\} \subseteq \Z,
\]
and the central quantity is its cardinality $\card{f(A)}$. How much can a polynomial compress
or expand a finite set? This is a load-bearing sub-question in additive combinatorics,
including the theory of expanders, the sum--product phenomenon, and the modern circle of
power-saving estimates for polynomial images of sets.

State-of-the-art results in that circle are asymptotic and depend on hard geometric input.
Our aim is complementary: we extract the exact, unconditional backbone beneath all of them,
with every constant explicit. Everything follows from one elementary principle---a degree-$k$
polynomial equation has at most $k$ solutions---together with elementary real analysis.

\subsection{Results at a glance}
\begin{enumerate}[leftmargin=2em]
  \item \textbf{Fiber lower bound (Theorem~\ref{thm:fiber}).}
        $\card{A} \le k\,\card{f(A)}$ for $\deg f = k \ge 1$.
  \item \textbf{Power-saving upper bound (Theorem~\ref{thm:upper}).}
        $\card{f(A)} \le \card{A}^{\,k - 1/k^2}$ for $\deg f = k \ge 2$, $A$ nonempty.
  \item \textbf{The corridor (Theorem~\ref{thm:corridor}).}
        $\card{A}/k \le \card{f(A)} \le \card{A}^{k-1/k^2}$.
  \item \textbf{Sharpness (Theorems~\ref{thm:upperattained}--\ref{thm:lowerattained}).}
        Both walls are attained.
  \item \textbf{Multiplicativity (Theorem~\ref{thm:mult}).}
        $\card{A} \le (k m)\,\card{(q\circ p)(A)}$, with tower constant $1/k^{2r}$.
\end{enumerate}

\section{Definitions}

\begin{definition}[Minkowski image]
For $f \in \Z[x]$ and finite $A \subseteq \Z$, the Minkowski image is
$f(A) = \{f(a) : a \in A\}$, the image of $A$ under the evaluation map $a \mapsto f(a)$.
\end{definition}

\begin{definition}[Fiber]
For $b \in f(A)$, the \emph{fiber} over $b$ is $\{a \in A : f(a) = b\}$.
\end{definition}

\begin{definition}[Power-saving constant]
For an integer $k \ge 1$ set $c(k) = 1/k^2$, the \emph{power-saving constant at degree $k$};
$k - c(k)$ is the \emph{power-saving exponent}.
\end{definition}

Throughout, ``monic degree $k$'' means $f(x) = x^k + (\text{lower-order terms})$ with integer
coefficients. The lower-bound results do not use monicity; only the degree matters.

\section{The lower bound: polynomials are at most $k$-to-one}

\begin{theorem}[Fiber lower bound]\label{thm:fiber}
Let $f \in \Z[x]$ have degree $k \ge 1$ and let $A \subseteq \Z$ be finite. Then
\[
  \card{A} \le k\,\card{f(A)}, \qquad\text{equivalently}\qquad \card{f(A)} \ge \frac{\card{A}}{k}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Partition $A$ over its image: $A = \bigsqcup_{b \in f(A)} \{a \in A : f(a) = b\}$. Fix
$b \in f(A)$; every $a$ in the fiber over $b$ satisfies $f(a) - b = 0$, so $a$ is a root of
$g_b(x) = f(x) - b$. Since $\deg f = k \ge 1$, the shift $g_b$ is nonzero with
$\deg g_b \le k$, hence has at most $k$ distinct roots, so the fiber has size $\le k$. Summing
over the $\card{f(A)}$ fibers, $\card{A} \le k\,\card{f(A)}$.
\end{proof}

\begin{remark}
Theorem~\ref{thm:fiber} is the universal obstruction to collapse; it uses only the degree
bound on the number of roots and holds for arbitrary (not necessarily monic) integer
polynomials.
\end{remark}

\section{The upper bound and the power-saving constant}

\begin{lemma}[Admissibility of $c(k)$]\label{lem:adm}
For every integer $k \ge 2$, \ $1 \le k - c(k) = k - 1/k^2 < k$.
\end{lemma}

\begin{proof}[Proof sketch]
The right inequality holds since $c(k) > 0$. For the left, $1/k^2 \le 1 \le k-1$ (as
$k \ge 2$); rearranging $1/k^2 \le k-1$ gives $1 + 1/k^2 \le k$, i.e. $1 \le k - 1/k^2$.
\end{proof}

\begin{lemma}[Real power-saving inequality]\label{lem:rpow}
For integers $n \ge 1$ and $k \ge 2$, \ $n \le n^{\,k - 1/k^2}$.
\end{lemma}

\begin{proof}[Proof sketch]
Since $n \ge 1$, $t \mapsto n^t$ is nondecreasing; by Lemma~\ref{lem:adm} the exponent is
$\ge 1$, so $n = n^1 \le n^{\,k - 1/k^2}$.
\end{proof}

\begin{theorem}[Power-saving upper bound]\label{thm:upper}
Let $f \in \Z[x]$ have degree $k \ge 2$ and let $A \subseteq \Z$ be nonempty finite. Then
$\card{f(A)} \le \card{A}^{\,k - 1/k^2}$.
\end{theorem}

\begin{proof}[Proof sketch]
An image never exceeds its domain, so $\card{f(A)} \le \card{A}$. As $A$ is nonempty,
$\card{A} \ge 1$, and Lemma~\ref{lem:rpow} gives $\card{A} \le \card{A}^{\,k-1/k^2}$. Chain
the two.
\end{proof}

\begin{remark}
The true content on the upper side is $\card{f(A)} \le \card{A}$; the exponent $k-1/k^2$ only
rephrases it in the power-saving normalization. Section~\ref{sec:sharp} shows this cannot be
improved to any exponent below $1$.
\end{remark}

\section{The corridor}

\begin{theorem}[Two-sided power-saving corridor]\label{thm:corridor}
Let $f \in \Z[x]$ be monic of degree $k \ge 2$ and let $A \subseteq \Z$ be nonempty finite.
Then
\[
  \frac{\card{A}}{k} \;\le\; \card{f(A)} \;\le\; \card{A}^{\,k - 1/k^2}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The lower bound is Theorem~\ref{thm:fiber} (needing only $k \ge 1$); the upper bound is
Theorem~\ref{thm:upper}.
\end{proof}

\section{Sharpness of both walls}\label{sec:sharp}

\begin{theorem}[Upper wall attained --- no expansion]\label{thm:upperattained}
For every $k \ge 1$ and $n \ge 0$, $f(x) = x^k$ is injective on $A = \{0,1,\dots,n-1\}$, so
$\card{f(A)} = \card{A} = n$.
\end{theorem}

\begin{proof}[Proof sketch]
On the nonnegative integers $m \mapsto m^k$ is strictly increasing ($k \ge 1$), hence
injective, so no two elements of $A$ collide.
\end{proof}

\begin{remark}
Hence the exponent in $\card{f(A)} \le \card{A}^{\,k-c}$ cannot drop below $1$: there is no
universal super-saving $\card{f(A)} \le \card{A}^{1-\varepsilon}$.
\end{remark}

\begin{theorem}[Lower wall attained --- factor-$k$ collapse]\label{thm:lowerattained}
For $f(x) = x^2$ (so $k=2$) and $A = \{-n,\dots,n\}$ (size $2n+1$),
$2\,\card{f(A)} = \card{A} + 1$.
\end{theorem}

\begin{proof}[Proof sketch]
Since $a^2 = (-a)^2$, the image of squaring over $\{-n,\dots,n\}$ equals its image over
$\{0,\dots,n\}$; squaring is injective on nonnegatives, so that image has $n+1$ elements.
Thus $\card{f(A)} = n+1$ and $\card{A} = 2n+1$, giving $2(n+1) = (2n+1)+1$.
\end{proof}

\begin{remark}
This saturates $\card{A} \le k\,\card{f(A)}$ with $k=2$ up to the unavoidable $+1$ from the
fixed point $0$; the factor $k$ in the lower wall is best possible.
\end{remark}

\section{Multiplicativity under composition}

\begin{lemma}[Composite image equals iterated image]\label{lem:comp}
For $p, q \in \Z[x]$ and finite $A \subseteq \Z$, \ $(q \circ p)(A) = q(p(A))$.
\end{lemma}

\begin{proof}[Proof sketch]
Elementwise $(q\circ p)(a) = q(p(a))$, so the image of $A$ under $q\circ p$ is the image
under $q$ of the image under $p$.
\end{proof}

\begin{theorem}[Multiplicativity of the fiber bound]\label{thm:mult}
Let $p, q \in \Z[x]$ with $\deg p = k \ge 1$ and $\deg q = m \ge 1$. Then for every finite
$A \subseteq \Z$,
\[
  \card{A} \;\le\; (k m)\,\card{(q \circ p)(A)}, \qquad \deg(q\circ p) = k m.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Set $B = p(A)$. Apply Theorem~\ref{thm:fiber} twice: $\card{A} \le k\,\card{B}$ and
$\card{B} \le m\,\card{q(B)}$. Combining, $\card{A} \le k m\,\card{q(B)}$; by
Lemma~\ref{lem:comp}, $q(B) = (q\circ p)(A)$. Finally $\deg(q\circ p) = \deg q\cdot\deg p = m k$.
\end{proof}

\begin{remark}
The proof does not apply the single-map fiber bound to $q\circ p$ directly; it chains two
separate applications through $B = p(A)$. Each fiber bound is tight in isolation and $B$ is a
bona fide finite set, so the loss is \emph{exactly} multiplicative---never worse than $k m$.
\end{remark}

\begin{theorem}[Composite corridor]\label{thm:compcorridor}
Let $\deg p = k \ge 1$, $\deg q = m \ge 1$, with $K := \deg(q\circ p) = k m \ge 2$, and let
$A$ be nonempty finite. Then
\[
  \frac{\card{A}}{K} \;\le\; \card{(q\circ p)(A)} \;\le\; \card{A}^{\,K - 1/K^2}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The lower bound is Theorem~\ref{thm:mult}; the upper bound is Theorem~\ref{thm:upper} applied
to the composite of degree $K$.
\end{proof}

\begin{corollary}[Towers]\label{cor:tower}
For an $r$-fold composition of degree-$k$ monic polynomials the composite degree is $k^r$ and
the power-saving constant is $c = 1/k^{2r}$.
\end{corollary}

\begin{proof}[Proof sketch]
Iterate Theorem~\ref{thm:mult}: each layer multiplies the degree factor by $k$, giving
$\card{A} \le k^r\,\card{F(A)}$ for the $r$-fold composite $F$ of degree $k^r$; the composite
corridor at $K = k^r$ carries $c(K) = 1/K^2 = 1/k^{2r}$.
\end{proof}

The corridor is thus \emph{functorial}: each layer contributes its own degree factor, and the
admissible power-saving constant decays geometrically with the number of layers.

\section{Algorithms}

\paragraph{Algorithm A (Corridor certificate).}
Given $f$ (as coefficients) and finite $A$, compute $\card{f(A)}$ by evaluation and
deduplication, then return $(\card{A}/k,\ \card{f(A)},\ \card{A}^{\,k-1/k^2})$ and verify the
corridor. Cost: $O(\card{A}\,k)$ evaluations plus $O(\card{A}\log\card{A})$ deduplication.

\paragraph{Algorithm B (Composition-chain verifier).}
Given $p,q,A$, form $B = p(A)$ and $C = q(B)$ by two evaluation passes, build $q\circ p$
symbolically, evaluate on $A$ to obtain $D$, assert $C = D$ (Lemma~\ref{lem:comp}), and check
$\card{A} \le (\deg p\cdot\deg q)\card{D}$ (Theorem~\ref{thm:mult}). Cost: two evaluation
passes plus one composition of cost $O((k m)^2)$.

\section{Applications and discussion}

\textbf{Baseline for expansion theorems.} Theorem~\ref{thm:corridor} is the exact elementary
baseline against which expansion results are measured; Theorem~\ref{thm:upperattained} shows
the floor cannot deliver growth, so any $\delta>0$ in $\card{f(A)} \ge \card{A}^{1+\delta}$
must come from the interplay of additive and multiplicative structure.

\textbf{Pipelines of maps.} Theorem~\ref{thm:mult} and Corollary~\ref{cor:tower} quantify how
compression accumulates under chaining; the decay $1/k^{2r}$ gives a budget for how many
layers a pipeline tolerates before non-collapse becomes vacuous.

\textbf{Sharp constants.} With all constants explicit and both walls attained, the corridor
serves as a computational certificate: image sizes outside it signal an error, and sizes near
a wall pinpoint extremal (progression-like or symmetric) structure of $A$.

\section{Future directions}
\begin{enumerate}[leftmargin=2em]
  \item \textbf{Genuine expansion requires curvature.} For non-affine monic $f$ of degree
        $k\ge2$, is there explicit $\delta(k)>0$ with $\card{f(A)} \ge \card{A}^{1+\delta}$
        or $\card{A+A} \ge \card{A}^{1+\delta}$ for all finite $A$? Progressions keep $f$
        injective, so expansion must break either the additive or the multiplicative
        structure.
  \item \textbf{Optimality of $1/k^{2r}$.} Is $c = 1/k^{2r}$ best possible among constants
        depending only on the composite degree $k^r$?
  \item \textbf{Mixed sum--image corridor.} Does $\card{f(A)+A} \ge c_k\,\card{A}^{1+1/k}$
        hold with explicit $c_k>0$? Adding $A$ back reintroduces additive structure, and the
        fiber bound supplies the slack $1/k$.
  \item \textbf{Corridor stability.} If $\|f-g\| \le 1$ in the coefficient sup-norm, does
        $\big|\card{f(A)} - \card{g(A)}\big| \le C_k\,\card{A}^{1-1/k^2}$ hold for all finite
        $A$?
\end{enumerate}

\section{Conclusion}
We isolated the exact, unconditional skeleton beneath power-saving estimates for polynomial
images of finite integer sets: the corridor $\card{A}/k \le \card{f(A)} \le \card{A}^{k-1/k^2}$
with explicit constant $c(k)=1/k^2$, sharp at both walls and multiplicative under composition
with tower constant $1/k^{2r}$. The floor is pure algebra; the ceiling marks the limit of what
algebra alone guarantees. The corridor secures the elementary territory and points to exactly
where deeper, incidence-geometric methods must take over.

