from __future__ import annotations
from typing import List, Sequence, Tuple

Poly = List[int]

def poly_eval(coeffs: Poly, x: int) -> int:
    r, p = 0, 1
    for c in coeffs:
        r += c * p
        p *= x
    return r

def poly_degree(coeffs: Poly) -> int:
    return max((i for i, c in enumerate(coeffs) if c != 0), default=0)

def corridor(coeffs: Poly, A: Sequence[int]) -> Tuple[float, int, float]:
    k = poly_degree(coeffs)
    n = len(set(A))
    img = {poly_eval(coeffs, a) for a in A}
    return n / k, len(img), n ** (k - 1.0 / (k * k))

if __name__ == "__main__":
    tests = [
        ("x^2", [0, 0, 1], list(range(-5, 6))),
        ("x^3 + x", [0, 1, 0, 1], list(range(-8, 9))),
        ("x^4 - 3x^2 + 1", [1, 0, -3, 0, 1], list(range(-9, 10))),
    ]
    for name, c, A in tests:
        lo, size, hi = corridor(c, A)
        ok = lo <= size <= hi + 1e-9
        print(f"{name:<16} |A|={len(set(A)):<3} {lo:8.3f} <= {size:<4} <= {hi:12.3f}  "
              f"[{'OK' if ok else 'FAIL'}]")

