from typing import List

def image_size(f, A: List[int]) -> int:
    return len({f(a) for a in A})

if __name__ == "__main__":
    print("Upper wall  (x^k on {0..n-1}: |f(A)| = |A|):")
    for k in (2, 3, 4):
        for n in (5, 12, 25):
            A = list(range(n))
            assert image_size(lambda x, k=k: x ** k, A) == n
