from __future__ import annotations
from typing import List

Poly = List[int]

def peval(c: Poly, x: int) -> int:
    r, p = 0, 1
    for a in c:
        r += a * p
        p *= x
    return r

def pmul(a: Poly, b: Poly) -> Poly:
    o = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            o[i + j] += ai * bj
    return o

def compose(q: Poly, p: Poly) -> Poly:
    res: Poly = [0]
    for c in reversed(q):
        res = pmul(res, p)
        res = (res + [0])[: max(len(res), 1)]
        res[0] += c
    return res

def deg(c: Poly) -> int:
    return max((i for i, a in enumerate(c) if a != 0), default=0)

if __name__ == "__main__":
    p, q = [0, 0, 1], [0, 0, 1]           # x^2, x^2 -> x^4
    comp = compose(q, p)
    k, m = deg(p), deg(q)
    for n in (5, 9, 13, 21):
        A = list(range(-n, n + 1))
        B = {peval(p, a) for a in A}
        C = {peval(q, b) for b in B}
        D = {peval(comp, a) for a in A}
        assert C == D
        print(f"|A|={len(A):<3} |(qop)(A)|={len(D):<3} "
              f"check |A| <= k*m*|.|: {len(A)} <= {k*m*len(D)}  OK")
    print("Tower constants 1/k^(2r):")
    for kk in (2, 3):
        for r in range(1, 5):
            print(f"  k={kk} r={r} deg=k^r={kk**r:<4} c=1/k^(2r)={1/kk**(2*r):.6g}")

