from typing import List, Sequence, Tuple

Poly = List[int]

def poly_eval(coeffs: Poly, x: int) -> int:
    result, power = 0, 1
    for c in coeffs:
        result += c * power
        power *= x
    return result

def poly_degree(coeffs: Poly) -> int:
    return max((i for i, c in enumerate(coeffs) if c != 0), default=0)

def fiber_lower_bound(f: Poly, A: Sequence[int]) -> Tuple[float, int]:
    """Return (|A|/k, |f(A)|) and assert the fiber bound |A| <= k*|f(A)|."""
    k: int = poly_degree(f)
    image = {poly_eval(f, a) for a in A}
    n: int = len(set(A))
    assert n <= k * len(image), "fiber bound violated"
    return n / k, len(image)

def power_saving_constant(k: int) -> float:
    return 1.0 / (k * k)

def power_saving_ceiling(k: int, n: int) -> float:
    """Corridor ceiling n^(k - 1/k^2); requires k >= 2, n >= 1."""
    assert k >= 2 and n >= 1
    exponent: float = k - power_saving_constant(k)
    assert exponent >= 1.0  # admissibility of the constant
    return float(n) ** exponent

from typing import List, Sequence

Poly = List[int]

def poly_eval(coeffs: Poly, x: int) -> int:
    result, power = 0, 1
    for c in coeffs:
        result += c * power
        power *= x
    return result

def poly_mul(a: Poly, b: Poly) -> Poly:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            out[i + j] += ai * bj
    return out

def poly_compose(q: Poly, p: Poly) -> Poly:
    result: Poly = [0]
    for c in reversed(q):
        result = poly_mul(result, p)
        if not result:
            result = [0]
        result[0] += c
    return result

def poly_degree(coeffs: Poly) -> int:
    return max((i for i, c in enumerate(coeffs) if c != 0), default=0)

def verify_composition(p: Poly, q: Poly, A: Sequence[int]) -> int:
    B = {poly_eval(p, a) for a in A}
    C = {poly_eval(q, b) for b in B}
    comp = poly_compose(q, p)
    D = {poly_eval(comp, a) for a in A}
    assert C == D, "(q o p)(A) != q(p(A))"
    k, m = poly_degree(p), poly_degree(q)
    assert len(set(A)) <= k * m * len(D), "multiplicativity violated"
    return len(D)
